class HardwareIPs(object):
    """IP base 192.168.253. is hardcoded and the same for all devices.
    Last part is calculated basing on board to which device is plugged,
    device's type and CPU for which IP is assigned"""

    ip_base = "192.168.253."
    board_schema = {0: '1', 1: '2'}
    hw_type_schema = {'asik': '0', 'abil_1': '1', 'abil_2': '2', 'abil_3': '3'}
    cpu_schema = {'xeon_master': '0', 'xeon_slave': '1', 'loner': '2'}

    @classmethod
    def get_cpu_ip(cls, board_slot, hw_type, cpu_name):
        cpu_ip = cls.ip_base + cls.board_schema[board_slot] + cls.hw_type_schema[hw_type] + cls.cpu_schema[cpu_name]
        return cpu_ip
